def test_non_constant_v3():
    K_limit = 10000
    y = [0] * (K_limit + 1)
    for i in range(1, 1088):
        y[i] = i

    for k in range(1088, K_limit + 1):
        S_k = set()
        for n in range(32, (k - 1024) // 2 + 1):
            S_k.add(y[k-n])
            S_k.add(y[n])

        choices = [v for v in S_k if v != y[k-1]]
        if not choices:
            y[k] = y[k-1]
        else:
            y[k] = choices[0]

    constant_from = -1
    for k in range(1088, K_limit + 1):
        if y[k] == y[k-1]:
            is_constant = True
            for j in range(k, K_limit + 1):
                if y[j] != y[k]:
                    is_constant = False
                    break
            if is_constant:
                constant_from = k
                break

    print(f"Eventually constant from: {constant_from}")

test_non_constant_v3()

def check_K_final(K):
    for k in range(1088, 2*K + 1024):
        # Condition: there exists n in [32, (k-1024)//2] such that n >= K or k-n >= K
        # This is equivalent to:
        # (k-1024)//2 >= K OR (k-K >= 32 and (k-1024)//2 >= 32)
        cond1 = (k - 1024) // 2 >= K
        cond2 = (k - K >= 32) and ((k - 1024) // 2 >= 32)
        if not (cond1 or cond2):
            return False
    return True

for K in range(1050, 1065):
    print(f"K={K}: {check_K_final(K)}")

